update runtime_config_definitions set data_type='INTEGER', validation_rule='{"minimum":1,"type":"integer","maximum":1000}'::jsonb, ui_metadata='{"categoryId":"adapter-execution","displayName":"Circuit breaker failure threshold","description":"Consecutive executor failures required before a circuit enters the open state.","recommended":"5 failures unless provider-specific evidence supports another threshold","effect":"Subsequent failure recording","impactPositive":"Lets operators tune sensitivity to repeated executor failures without restart.","impactTradeoff":"A threshold that is too low can open on transient failures; too high delays protection.","advancedKeyVisible":true,"categoryDisplayName":"Adapter Execution","categoryDescription":"Adapter execution limits, timeout and resilience controls.","categoryOrder":50}'::jsonb, schema_version=15, source_ref='contracts/current/configuration/definitions/definition-registry-v41-c3r2x2.json', source_fingerprint='139a76afab04d5fb6b50553b0fb0a59e15260a116d5e7216bfef40f3cb89afbd', synchronized_at=now() where definition_key='adapter-executor.circuit-breaker.failure-threshold';
update runtime_config_definitions set data_type='DURATION', validation_rule='{"minimum":"PT0.001S","type":"duration","maximum":"PT24H"}'::jsonb, ui_metadata='{"categoryId":"adapter-execution","displayName":"Circuit breaker open duration","description":"How long an opened executor circuit remains unavailable before normal evaluation resumes.","recommended":"PT1M unless provider recovery behavior requires another duration","effect":"Subsequent circuit opening","impactPositive":"Allows provider recovery windows to be tuned without restarting Core.","impactTradeoff":"Long durations delay recovery after a provider becomes healthy; very short durations can increase retry pressure.","advancedKeyVisible":true,"categoryDisplayName":"Adapter Execution","categoryDescription":"Adapter execution limits, timeout and resilience controls.","categoryOrder":50}'::jsonb, schema_version=15, source_ref='contracts/current/configuration/definitions/definition-registry-v41-c3r2x2.json', source_fingerprint='92f8a3bf87932917c98a4b38e7c136e638d91b43c2e739d1ec63e348d143c25e', synchronized_at=now() where definition_key='adapter-executor.circuit-breaker.open-duration';
