do $$ declare v_authorized integer; v_incomplete integer; begin
select count(*) into v_authorized from runtime_config_definitions where migration_authorized=true and admin_editable=true;
if v_authorized<>241 then raise exception 'C3R2X2_AUTHORIZED_COUNT_DRIFT expected=241 actual=%',v_authorized; end if;
select count(*) into v_incomplete from runtime_config_definitions where migration_authorized=true and admin_editable=true and ((data_type in ('INTEGER','LONG','DECIMAL','DURATION') and (not (validation_rule ? 'minimum') or not (validation_rule ? 'maximum'))) or (data_type='ENUM' and not (validation_rule ? 'allowedValues')) or (data_type='STRING' and not (validation_rule ?| array['minLength','maxLength','allowedValues','enum','allowedCsvValues','pattern'])) or (data_type='URI' and not (validation_rule ?| array['allowedSchemes','minLength','maxLength','pattern'])));
if v_incomplete<>0 then raise exception 'C3R2X2_DEFINITION_CONTRACT_INCOMPLETE count=%',v_incomplete; end if;
if exists(select 1 from runtime_config_inventory_governance where status in ('MIGRATED','LEGACY_RETIRED') and configuration_key in (select definition_key from runtime_config_definitions where source_ref='contracts/current/configuration/definitions/definition-registry-v41-c3r2x2.json')) then raise exception 'C3R2X2_PREMATURE_SINGLE_AUTHORITY_CUTOVER'; end if;
end $$;
